from __future__ import print_function
# from builtins import range
import sys
import argparse
import time
from scapy.all import *


def _parse_arguments():
    parser = argparse.ArgumentParser(description="Automatic SCF generator script")
    parser.add_argument("-c", "--capture_interface", help="Interface to capture the traffic", required=True)
    parser.add_argument("-r", "--replay_interface", help="Interface to replay the traffic", required=True)
    parser.add_argument("-f", "--capture_filter", help="Capture filter", required=False)
    parser.add_argument("-n", "--count", help="Number of packets to send", required=False, default=1)
    parser.add_argument("-d", "--delay", help="Delay before sending", required=False, default=0)
    parser.add_argument("-m", "--modify", help="Packet Field to Modify", required=False)

    argument = parser.parse_args()
    return argument.capture_interface, argument.replay_interface, argument.capture_filter, argument.count,\
           argument.delay, argument.modify


capture_interface, replay_interface, capture_filter, count, delay, modify_string = _parse_arguments()

print("Waiting for packet to be captured")
captured_packets_list = sniff(iface=capture_interface, filter=capture_filter,
                              count=1, timeout=300)

if not captured_packets_list:
    print("No Packet captured in 5 mins!!")
    sys.exit()
print("Captured packet:")
captured_packets_list[0].show()
print("\n")

if modify_string is not None:
    key, value = modify_string.split("=")
    print("Parameters to modify, and value:")
    print((key, value))
    print("Protocol and parameter:")
    proto, param = key.split(".")
    setattr(captured_packets_list[0][proto], param, int(1234))
    print((proto, param))
    captured_packets_list[0].show()

print("Waiting for {} seconds".format(delay))
time.sleep(int(delay))
for i in range(0, int(count)):
    print("Replaying Packet: {}".format(i))
    sendp(captured_packets_list[0], iface=replay_interface)
